    def transform(self, data):
        # Identity transform
        return data

def make_preprocessor():
    return MyPreprocessor()

class HitClassifier(nn.Module):
    def __init__(self, in_features):
        super().__init__()
        # No learnable parameters; clustering-only model

    def forward(self, batch_x):
        # batch_x: Tensor of shape (N,4) columns = (r, theta, z, layer_id)
        # Convert to CPU numpy for DBSCAN
        X = batch_x.detach().cpu().numpy()        # (N,4)
        r     = X[:, 0]                           # (N,)
        theta = X[:, 1]                           # (N,)
        z     = X[:, 2]                           # (N,)
        # Convert cylindrical to Cartesian for clustering
        coords = np.stack([
            r * np.cos(theta),                    # (N,)
            r * np.sin(theta),                    # (N,)
            z                                     # (N,)
        ], axis=1)                                # (N,3)
        # DBSCAN clusters neighboring hits into tracks
        clustering = DBSCAN(eps=5.0, min_samples=4).fit(coords)
        labels = clustering.labels_               # (N,), -1 for noise
        # Remap labels: non-noise clusters -> 0..C-1, noise each as unique id (>C-1)
        unique = np.unique(labels)
        # Map old non-negative labels to new contiguous ids
        label_map = {lab: i for i, lab in enumerate(unique) if lab >= 0}
        next_noise_id = len(label_map)
        remapped = np.empty_like(labels)
        for idx, lab in enumerate(labels):
            if lab >= 0:
                remapped[idx] = label_map[lab]
            else:
                remapped[idx] = next_noise_id
                next_noise_id += 1
        preds = torch.from_numpy(remapped).to(batch_x.device)
        return preds

def make_model(in_features):
    return HitClassifier(in_features)

